function [rho] = density_member(h, t_epoch, level)
%DENSITY_MEMBER  The density at altitude h at one member of the bundle. The place is the equator on the diurnal bulge (local solar time
%   14 h, where DTM2020's daily maximum lies), the day of the year is the epoch's fraction of its year: the row says how dense
%   the air is at worst along the orbit, not where.
%   h: real[km] (passed in m)
%   t_epoch: real[yr] (passed in s)
%   level: SolarActivity (passed a choice, as its option's number)
%   returns rho: real[kg/m^3] (passed in kg/m^3)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    rho = 0;
    [f107, f107a, kp] = asils.models.atmosbundle.bundle_activity(level);
    years = (t_epoch / 31557600);
    doy = (1 + (365 * (years - floor(years))));
    rho = (asils.models.atmosbundle.dtm_density((h / 1000), 0, 0, 14, doy, f107, f107a, kp) * 1);
end
